export const CUSTOM_NODE_SYMBOL_OPTIONS: NodeShapeOption[] = Object.values(CUSTOM_NODE_SHAPE_DEFINITIONS)
    .map(({ key, value, name, groupKey }) => ({ key, value, name, groupKey }));

export const NODE_SYMBOL_OPTIONS: NodeShapeOption[] = [
    ...BASIC_NODE_SYMBOL_OPTIONS,
    ...CUSTOM_NODE_SYMBOL_OPTIONS,
];

const SUPPORTED_NODE_SHAPE_KEYS = new Set(NODE_SYMBOL_OPTIONS.map(({ key }) => key));

const LEGACY_NODE_SHAPE_KEY_MAP: Record<string, string> = {
    symbolCircle: 'ellipse',
    symbolTriangle: 'triangle',
    symbolTriangleDown: 'triangle',
    symbolSquare: 'rectangle',
    square: 'rectangle',
    symbolDiamond: 'rhomboid',
    symbolDiamondAlt: 'rhomboid',
    symbolDiamondSquare: 'diamond',
    symbolOctagonAlt: 'heptagon',
    symbolHexagonAlt: 'heptagon',
    symbolPentagon: 'pentagon',
    symbolHexagon: 'hexagon',
    symbolCross: 'barrel',
    symbolOctagon: 'octagon',
    symbolStar: 'star',
    symbolTriangleLeft: 'tag',
    symbolTriangleRight: 'tag',
    symbolX: 'vee',
    symbolWye: 'vee',
    mosiquito: 'mosquito',
    apple: 'fruits',
};

interface NodeShapeStyleMapping {
    nodeSymbolsTable?: Record<string, any>;
    nodeSymbolsTableKeys?: Record<string, any>;
}

export function normalizeNodeShapeKey(shapeKey: string | null | undefined): string | null {
    if (!shapeKey) {
        return null;
    }

    if (SUPPORTED_NODE_SHAPE_KEYS.has(shapeKey)) {
        return shapeKey;
    }

    const legacyShapeKey = LEGACY_NODE_SHAPE_KEY_MAP[shapeKey];
    if (legacyShapeKey && SUPPORTED_NODE_SHAPE_KEYS.has(legacyShapeKey)) {
        return legacyShapeKey;
    }

    return null;
}

export function resolveNodeShapeKey(shapeKey: string | null | undefined, fallbackShapeKey: string = DEFAULT_NODE_SHAPE_KEY): string {
    return normalizeNodeShapeKey(shapeKey) ?? fallbackShapeKey;
}

export function resolveNodeShapeForNode(
    node: any,
    widgets: Record<string, any> | null | undefined,
    style: NodeShapeStyleMapping | null | undefined,
    nodeSymbolMap?: ((value: any) => string) | null
): string {
    const defaultShape = resolveNodeShapeKey(widgets?.['node-symbol']);
    const symbolVariable = widgets?.['node-symbol-variable'];

    if (!node || !symbolVariable || symbolVariable === 'None') {
        return defaultShape;
    }

    const nodeValue = node[symbolVariable];
    const tableKeys = style?.nodeSymbolsTableKeys?.[symbolVariable];
    const tableShapes = style?.nodeSymbolsTable?.[symbolVariable];

    if (Array.isArray(tableKeys) && Array.isArray(tableShapes)) {
        const tableIndex = tableKeys.findIndex(value => value === nodeValue || `${value}` === `${nodeValue}`);
        if (tableIndex >= 0 && tableIndex < tableShapes.length) {
            return resolveNodeShapeKey(tableShapes[tableIndex], defaultShape);
        }
    }

    if (nodeSymbolMap) {
        return resolveNodeShapeKey(nodeSymbolMap(nodeValue), defaultShape);
    }

    return defaultShape;
}

export function isCustomNodeShape(shapeKey: string | null | undefined): boolean {
    const normalizedShapeKey = normalizeNodeShapeKey(shapeKey);
    return normalizedShapeKey !== null && normalizedShapeKey in CUSTOM_NODE_SHAPE_DEFINITIONS;
}

export function resolveNodeShapeCytoscapeShape(shapeKey: string): string {
    const normalizedShapeKey = resolveNodeShapeKey(shapeKey);
    if (!isCustomNodeShape(normalizedShapeKey)) {
        return normalizedShapeKey;
    }

    return CUSTOM_NODE_SHAPE_DEFINITIONS[normalizedShapeKey].cytoscapeShape;
}

function sanitizeSvgColor(color: string | null | undefined): string {
    return (color || '#000000').replace(/"/g, '&quot;');
}

function sanitizeSvgOpacity(opacity: number | null | undefined): number {
    const numericOpacity = Number(opacity);
    if (!Number.isFinite(numericOpacity)) {
        return 1;
    }

    return Math.min(1, Math.max(0, numericOpacity));
}

function buildPaddedViewBox(viewBox: string, padding: number): string {
    const dimensions = viewBox.trim().split(/\s+/).map(value => Number(value));
    if (dimensions.length !== 4 || dimensions.some(value => Number.isNaN(value))) {
        return viewBox;
    }

    const [minX, minY, width, height] = dimensions;
    return `${minX - padding} ${minY - padding} ${width + (padding * 2)} ${height + (padding * 2)}`;
}

function buildCustomNodeShapeDataUri(
    definition: CustomNodeShapeDefinition,
    fillColor: string,
    strokeColor: string,
    strokeWidth: number,
    viewBoxPadding: number = 0,
    intrinsicCanvasSize?: { width: number; height: number },
    fillOpacity: number = 1
): string {
    const safeFill = sanitizeSvgColor(fillColor);
    const safeStroke = sanitizeSvgColor(strokeColor);
    const safeFillOpacity = sanitizeSvgOpacity(fillOpacity);
    const svgWidth = intrinsicCanvasSize?.width ?? definition.width;
    const svgHeight = intrinsicCanvasSize?.height ?? definition.height;
    const fillPath = `<path d="${definition.fillPath ?? definition.path}" fill="${safeFill}" fill-opacity="${safeFillOpacity}" stroke="none"/>`;
    const outlinePath = `<path d="${definition.path}" fill="none" stroke="${safeStroke}" stroke-width="${strokeWidth}" stroke-linecap="round" stroke-linejoin="round"/>`;
    const svg = `<?xml version="1.0" encoding="UTF-8"?><!DOCTYPE svg><svg xmlns="http://www.w3.org/2000/svg" width="${svgWidth}" height="${svgHeight}" viewBox="${buildPaddedViewBox(definition.viewBox, viewBoxPadding)}" preserveAspectRatio="xMidYMid meet" aria-hidden="true"><g transform="translate(0,${definition.height}) scale(1,-1)">${fillPath}${outlinePath}</g></svg>`;
    return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
}

function buildEllipseNodeShapeDataUri(
    fillColor: string,
    strokeColor: string,
    strokeWidth: number,
    viewBoxPadding: number = Math.max(20, strokeWidth),
    fillOpacity: number = 1
): string {
    const safeFill = sanitizeSvgColor(fillColor);
    const safeStroke = sanitizeSvgColor(strokeColor);
    const safeFillOpacity = sanitizeSvgOpacity(fillOpacity);
    const svg = `<?xml version="1.0" encoding="UTF-8"?><svg xmlns="http://www.w3.org/2000/svg" width="300" height="300" viewBox="${buildPaddedViewBox('0 0 300 300', viewBoxPadding)}" aria-hidden="true"><circle cx="150" cy="150" r="110" fill="${safeFill}" fill-opacity="${safeFillOpacity}" stroke="${safeStroke}" stroke-width="${strokeWidth}" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
    return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
}

function roundSvgCoordinate(value: number): number {
    return Number(value.toFixed(2));
}

function createNodeShapePoint(x: number, y: number): NodeShapePoint {
    return [roundSvgCoordinate(x), roundSvgCoordinate(y)];
}

function buildClosedPath(points: NodeShapePoint[]): string {
    if (!points.length) {
        return '';
    }

    const [firstPoint, ...remainingPoints] = points;
    const pathSegments = [`M ${firstPoint[0]} ${firstPoint[1]}`];
    for (const [x, y] of remainingPoints) {
        pathSegments.push(`L ${x} ${y}`);
    }

    pathSegments.push('Z');
    return pathSegments.join(' ');
}

function buildRegularPolygonPath(sides: number, radius: number = MAP_NODE_SHAPE_RADIUS, rotationRadians: number = -Math.PI / 2): string {
    const points: NodeShapePoint[] = [];
    for (let index = 0; index < sides; index++) {
        const angle = rotationRadians + ((Math.PI * 2 * index) / sides);
        points.push(createNodeShapePoint(
            MAP_NODE_SHAPE_CENTER + (radius * Math.cos(angle)),
            MAP_NODE_SHAPE_CENTER + (radius * Math.sin(angle))
        ));
    }

    return buildClosedPath(points);
}

function buildStarPath(points: number = 5, outerRadius: number = 112, innerRadius: number = 48, rotationRadians: number = -Math.PI / 2): string {
    const starPoints: NodeShapePoint[] = [];
    for (let index = 0; index < points * 2; index++) {
        const angle = rotationRadians + ((Math.PI * index) / points);
        const radius = index % 2 === 0 ? outerRadius : innerRadius;
        starPoints.push(createNodeShapePoint(
            MAP_NODE_SHAPE_CENTER + (radius * Math.cos(angle)),
            MAP_NODE_SHAPE_CENTER + (radius * Math.sin(angle))
        ));
    }

    return buildClosedPath(starPoints);
}

function buildBasicNodeShapePath(shapeKey: string): string | null {
    switch (shapeKey) {
        case 'triangle':
            return buildClosedPath([
                createNodeShapePoint(150, 35),
                createNodeShapePoint(262, 245),
                createNodeShapePoint(38, 245),
            ]);
        case 'rectangle':
            return buildClosedPath([
                createNodeShapePoint(50, 50),
                createNodeShapePoint(250, 50),
                createNodeShapePoint(250, 250),
                createNodeShapePoint(50, 250),
            ]);
        case 'rhomboid':
            return buildClosedPath([
                createNodeShapePoint(92, 45),
                createNodeShapePoint(255, 45),
                createNodeShapePoint(208, 255),
                createNodeShapePoint(45, 255),
            ]);
        case 'diamond':
            return buildClosedPath([
                createNodeShapePoint(150, 35),
                createNodeShapePoint(265, 150),
                createNodeShapePoint(150, 265),
                createNodeShapePoint(35, 150),
            ]);
        case 'pentagon':
            return buildRegularPolygonPath(5);
        case 'hexagon':
            return buildRegularPolygonPath(6);
        case 'heptagon':
            return buildRegularPolygonPath(7);
        case 'octagon':
            return buildRegularPolygonPath(8);
        case 'star':
            return buildStarPath();
        case 'tag':
            return buildClosedPath([
                createNodeShapePoint(40, 65),
                createNodeShapePoint(190, 65),
                createNodeShapePoint(260, 150),
                createNodeShapePoint(190, 235),
                createNodeShapePoint(40, 235),
            ]);
        case 'vee':
            return buildClosedPath([
                createNodeShapePoint(42, 60),
                createNodeShapePoint(105, 60),
                createNodeShapePoint(150, 155),
                createNodeShapePoint(195, 60),
                createNodeShapePoint(258, 60),
                createNodeShapePoint(173, 255),
                createNodeShapePoint(127, 255),
            ]);
        default:
            return null;
    }
}

function buildBarrelNodeShapeDataUri(
    fillColor: string,
    strokeColor: string,
    strokeWidth: number,
    viewBoxPadding: number = Math.max(20, strokeWidth),
    fillOpacity: number = 1
): string {
    const safeFill = sanitizeSvgColor(fillColor);
    const safeStroke = sanitizeSvgColor(strokeColor);
    const safeFillOpacity = sanitizeSvgOpacity(fillOpacity);
    const barrelPath = 'M 90 45 C 60 45 45 82 45 150 C 45 218 60 255 90 255 L 210 255 C 240 255 255 218 255 150 C 255 82 240 45 210 45 Z';
    const svg = `<?xml version="1.0" encoding="UTF-8"?><svg xmlns="http://www.w3.org/2000/svg" width="300" height="300" viewBox="${buildPaddedViewBox('0 0 300 300', viewBoxPadding)}" aria-hidden="true"><path d="${barrelPath}" fill="${safeFill}" fill-opacity="${safeFillOpacity}" stroke="${safeStroke}" stroke-width="${strokeWidth}" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
    return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
}

function buildBasicNodeShapeDataUri(
    shapeKey: string,
    fillColor: string,
    strokeColor: string,
    strokeWidth: number,
    viewBoxPadding: number = Math.max(20, strokeWidth),
    fillOpacity: number = 1
): string | null {
    if (shapeKey === 'ellipse') {
        return buildEllipseNodeShapeDataUri(fillColor, strokeColor, strokeWidth, viewBoxPadding, fillOpacity);
    }

    if (shapeKey === 'barrel') {
        return buildBarrelNodeShapeDataUri(fillColor, strokeColor, strokeWidth, viewBoxPadding, fillOpacity);
    }

    const path = buildBasicNodeShapePath(shapeKey);
    if (!path) {
        return null;
    }

    const safeFill = sanitizeSvgColor(fillColor);
    const safeStroke = sanitizeSvgColor(strokeColor);
    const safeFillOpacity = sanitizeSvgOpacity(fillOpacity);
    const svg = `<?xml version="1.0" encoding="UTF-8"?><svg xmlns="http://www.w3.org/2000/svg" width="300" height="300" viewBox="${buildPaddedViewBox('0 0 300 300', viewBoxPadding)}" aria-hidden="true"><path d="${path}" fill="${safeFill}" fill-opacity="${safeFillOpacity}" stroke="${safeStroke}" stroke-width="${strokeWidth}" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
    return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
}

function getSegmentedBorderArcPath(
    centerX: number,
    centerY: number,
    radius: number,
    startFraction: number,
    endFraction: number
): string {
    const startAngle = -Math.PI / 2 + startFraction * Math.PI * 2;
    const endAngle = -Math.PI / 2 + endFraction * Math.PI * 2;
    const startX = roundSvgCoordinate(centerX + radius * Math.cos(startAngle));
    const startY = roundSvgCoordinate(centerY + radius * Math.sin(startAngle));
    const endX = roundSvgCoordinate(centerX + radius * Math.cos(endAngle));
    const endY = roundSvgCoordinate(centerY + radius * Math.sin(endAngle));
    const largeArcFlag = endFraction - startFraction > 0.5 ? 1 : 0;

    return `M ${startX} ${startY} A ${radius} ${radius} 0 ${largeArcFlag} 1 ${endX} ${endY}`;
}

interface WeightedMixedNodeShapeSegment {
    segment: MixedNodeShapeSegment;
    startFraction: number;
    endFraction: number;
}

function formatSvgFraction(value: number): string {
    return Number(value.toFixed(6)).toString();
}

function getWeightedMixedNodeShapeSegments(segments: MixedNodeShapeSegment[]): WeightedMixedNodeShapeSegment[] {
    const validSegments = segments.filter(segment => Number(segment.weight ?? 1) > 0);
    const totalWeight = validSegments.reduce((sum, segment) => sum + Number(segment.weight ?? 1), 0);
    if (validSegments.length < 2 || totalWeight <= 0) {
        return [];
    }

    let startFraction = 0;
    return validSegments.map((segment, index) => {
        const segmentWeight = Number(segment.weight ?? 1);
        const endFraction = index === validSegments.length - 1
            ? 1
            : startFraction + (segmentWeight / totalWeight);
        const weightedSegment = { segment, startFraction, endFraction };
        startFraction = endFraction;

        return weightedSegment;
    });
}

function buildSegmentedCircleBorderPaths(
    segments: MixedNodeShapeSegment[],
    strokeWidth: number,
    radius: number = 124
): string {
    return getWeightedMixedNodeShapeSegments(segments).map(({ segment, startFraction, endFraction }) => {
        const path = getSegmentedBorderArcPath(150, 150, radius, startFraction, endFraction);
        return `<path d="${path}" fill="none" stroke="${sanitizeSvgColor(segment.color)}" stroke-opacity="${sanitizeSvgOpacity(segment.alpha)}" stroke-width="${strokeWidth}" stroke-linecap="butt"/>`;
    }).join('');
}

function buildSegmentedPathBorderPaths(
    path: string,
    segments: MixedNodeShapeSegment[],
    strokeWidth: number,
    extraAttributes: string = ''
): string {
    return getWeightedMixedNodeShapeSegments(segments).map(({ segment, startFraction, endFraction }) => {
        const dashLength = Math.max(0, endFraction - startFraction);
        const dashGap = Math.max(0, 1 - dashLength);

        return `<path d="${path}" fill="none" stroke="${sanitizeSvgColor(segment.color)}" stroke-opacity="${sanitizeSvgOpacity(segment.alpha)}" stroke-width="${strokeWidth}" stroke-linecap="butt" stroke-linejoin="round" pathLength="1" stroke-dasharray="${formatSvgFraction(dashLength)} ${formatSvgFraction(dashGap)}" stroke-dashoffset="${formatSvgFraction(-startFraction)}" ${extraAttributes}/>`;
    }).join('');
}

function buildSelectedPathBorder(path: string, selectedStrokeColor: string | null | undefined, strokeWidth: number, extraAttributes: string = ''): string {
    if (!selectedStrokeColor) {
        return '';
    }

    return `<path d="${path}" fill="none" stroke="${sanitizeSvgColor(selectedStrokeColor)}" stroke-width="${Math.max(3, strokeWidth + 4)}" stroke-linecap="round" stroke-linejoin="round" ${extraAttributes}/>`;
}

function buildSegmentedCustomShapeContent(
    definition: CustomNodeShapeDefinition,
    fillColor: string,
    strokeColor: string,
    strokeWidth: number,
    fillOpacity: number,
    segments: MixedNodeShapeSegment[],
    selectedStrokeColor?: string | null
): string {
    const safeFill = sanitizeSvgColor(fillColor);
    const safeStroke = sanitizeSvgColor(strokeColor);
    const safeFillOpacity = sanitizeSvgOpacity(fillOpacity);
    const vectorStrokeAttribute = 'vector-effect="non-scaling-stroke"';
    const selectedBorder = buildSelectedPathBorder(definition.path, selectedStrokeColor, strokeWidth, vectorStrokeAttribute);
    const segmentedBorder = buildSegmentedPathBorderPaths(definition.path, segments, strokeWidth, vectorStrokeAttribute);
    const fallbackBorder = segmentedBorder || `<path d="${definition.path}" fill="none" stroke="${safeStroke}" stroke-width="${strokeWidth}" stroke-linecap="round" stroke-linejoin="round" ${vectorStrokeAttribute}/>`;

    return [
        `<svg x="40" y="40" width="220" height="220" viewBox="${definition.viewBox}" preserveAspectRatio="xMidYMid meet">`,
        `<g transform="translate(0,${definition.height}) scale(1,-1)">`,
        `<path d="${definition.fillPath ?? definition.path}" fill="${safeFill}" fill-opacity="${safeFillOpacity}" stroke="none"/>`,
        selectedBorder,
        fallbackBorder,
        '</g>',
        '</svg>'
    ].join('');
}

function getBasicSegmentedShapePath(normalizedShapeKey: string): string | null {
    if (normalizedShapeKey === 'barrel') {
        return 'M 90 45 C 60 45 45 82 45 150 C 45 218 60 255 90 255 L 210 255 C 240 255 255 218 255 150 C 255 82 240 45 210 45 Z';
    }

    return buildBasicNodeShapePath(normalizedShapeKey);
}

function buildSegmentedBasicShapeContent(
    normalizedShapeKey: string,
    fillColor: string,
    strokeColor: string,
    strokeWidth: number,
    fillOpacity: number,
    segments: MixedNodeShapeSegment[],
    selectedStrokeColor?: string | null
): string {
    const safeFill = sanitizeSvgColor(fillColor);
    const safeStroke = sanitizeSvgColor(strokeColor);
    const safeFillOpacity = sanitizeSvgOpacity(fillOpacity);

    if (normalizedShapeKey === 'ellipse') {
        const selectedBorder = selectedStrokeColor
            ? `<circle cx="150" cy="150" r="124" fill="none" stroke="${sanitizeSvgColor(selectedStrokeColor)}" stroke-width="${Math.max(3, strokeWidth + 4)}"/>`
            : '';
        const segmentedBorder = buildSegmentedCircleBorderPaths(segments, strokeWidth);
        const fallbackBorder = segmentedBorder || `<circle cx="150" cy="150" r="124" fill="none" stroke="${safeStroke}" stroke-width="${strokeWidth}"/>`;

        return `<circle cx="150" cy="150" r="108" fill="${safeFill}" fill-opacity="${safeFillOpacity}" stroke="none"/>${selectedBorder}${fallbackBorder}`;
    }

    const path = getBasicSegmentedShapePath(normalizedShapeKey);

    if (!path) {
        const selectedBorder = selectedStrokeColor
            ? `<circle cx="150" cy="150" r="124" fill="none" stroke="${sanitizeSvgColor(selectedStrokeColor)}" stroke-width="${Math.max(3, strokeWidth + 4)}"/>`
            : '';
        const segmentedBorder = buildSegmentedCircleBorderPaths(segments, strokeWidth);
        const fallbackBorder = segmentedBorder || `<circle cx="150" cy="150" r="124" fill="none" stroke="${safeStroke}" stroke-width="${strokeWidth}"/>`;

        return `<circle cx="150" cy="150" r="108" fill="${safeFill}" fill-opacity="${safeFillOpacity}" stroke="none"/>${selectedBorder}${fallbackBorder}`;
    }

    const selectedBorder = buildSelectedPathBorder(path, selectedStrokeColor, strokeWidth);
    const segmentedBorder = buildSegmentedPathBorderPaths(path, segments, strokeWidth);
    const fallbackBorder = segmentedBorder || `<path d="${path}" fill="none" stroke="${safeStroke}" stroke-width="${strokeWidth}" stroke-linecap="round" stroke-linejoin="round"/>`;

    return `<path d="${path}" fill="${safeFill}" fill-opacity="${safeFillOpacity}" stroke="none"/>${selectedBorder}${fallbackBorder}`;
}

export function getSegmentedNodeShapeDataUri(
    shapeKey: string,
    fillColor: string,
    strokeColor: string,
    strokeWidth: number,
    fillOpacity: number = 1,
    segments: MixedNodeShapeSegment[] = [],
    selectedStrokeColor?: string | null
): string {
    const normalizedShapeKey = resolveNodeShapeKey(shapeKey);
    const safeStroke = sanitizeSvgColor(strokeColor);
    const safeStrokeWidth = Math.max(1, Number(strokeWidth) || 1);
    const shapeContent = isCustomNodeShape(normalizedShapeKey)
        ? buildSegmentedCustomShapeContent(CUSTOM_NODE_SHAPE_DEFINITIONS[normalizedShapeKey], fillColor, safeStroke, safeStrokeWidth, fillOpacity, segments, selectedStrokeColor)
        : buildSegmentedBasicShapeContent(normalizedShapeKey, fillColor, safeStroke, safeStrokeWidth, fillOpacity, segments, selectedStrokeColor);
    const svg = `<?xml version="1.0" encoding="UTF-8"?><svg xmlns="http://www.w3.org/2000/svg" width="300" height="300" viewBox="0 0 300 300" aria-hidden="true">${shapeContent}</svg>`;

    return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
}

export function getMapNodeShapeDataUri(shapeKey: string, fillColor: string, strokeColor: string, strokeWidth: number, fillOpacity: number = 1): string {
    const normalizedShapeKey = resolveNodeShapeKey(shapeKey);
    if (isCustomNodeShape(normalizedShapeKey)) {
        const definition = CUSTOM_NODE_SHAPE_DEFINITIONS[normalizedShapeKey];
        const squareCanvasSize = Math.max(definition.width, definition.height);

        // Leaflet map markers are rendered into square icon boxes. Keeping the
        // intrinsic SVG canvas square prevents custom shapes from stretching in
        // raster export paths that rely on the marker image dimensions.
        return buildCustomNodeShapeDataUri(
            definition,
            fillColor,
            strokeColor,
            strokeWidth,
            Math.max(20, strokeWidth),
            { width: squareCanvasSize, height: squareCanvasSize },
            fillOpacity
        );
    }

    const basicShapeDataUri = buildBasicNodeShapeDataUri(normalizedShapeKey, fillColor, strokeColor, strokeWidth, undefined, fillOpacity);
    if (basicShapeDataUri) {
        return basicShapeDataUri;
    }

    return buildEllipseNodeShapeDataUri(fillColor, strokeColor, strokeWidth, undefined, fillOpacity);
}

export function getTreeNodeShapeDataUri(shapeKey: string, fillColor: string, strokeColor: string, strokeWidth: number, fillOpacity: number = 1): string {
    const normalizedShapeKey = resolveNodeShapeKey(shapeKey);
    if (isCustomNodeShape(normalizedShapeKey)) {
        return buildCustomNodeShapeDataUri(
            CUSTOM_NODE_SHAPE_DEFINITIONS[normalizedShapeKey],
            fillColor,
            strokeColor,
            strokeWidth,
            undefined,
            undefined,
            fillOpacity
        );
    }

    const basicShapeDataUri = buildBasicNodeShapeDataUri(normalizedShapeKey, fillColor, strokeColor, strokeWidth, 0, fillOpacity);
    if (basicShapeDataUri) {
        return basicShapeDataUri;
    }

    return buildEllipseNodeShapeDataUri(fillColor, strokeColor, strokeWidth, 0, fillOpacity);
}

export function getTreeNodeShapeScale(shapeKey: string): number {
    const normalizedShapeKey = resolveNodeShapeKey(shapeKey);
    if (BASIC_NODE_SHAPE_KEYS.has(normalizedShapeKey)) {
        // Basic shapes are authored inside a ~220px footprint, so the tree overlay
        // needs a compensating scale factor to match the native leaf-circle size.
        return TREE_BASIC_NODE_SHAPE_SCALE;
    }

    return 1;
}

export function getCustomNodeShapeVectorData(shapeKey: string): CustomNodeShapeVectorData | null {
    const normalizedShapeKey = normalizeNodeShapeKey(shapeKey);
    if (!normalizedShapeKey || !isCustomNodeShape(normalizedShapeKey)) {
        return null;
    }

    const definition = CUSTOM_NODE_SHAPE_DEFINITIONS[normalizedShapeKey];
    return {
        width: definition.width,
        height: definition.height,
        path: definition.path,
        fillPath: definition.fillPath ?? definition.path
    };
}

export function getCustomNodeShapeData(shapeKey: string, nodeColor: string): Record<string, string> {
    const normalizedShapeKey = normalizeNodeShapeKey(shapeKey);
    if (!normalizedShapeKey) {
        return {};
    }

    if (!isCustomNodeShape(normalizedShapeKey)) {
        return {};
    }

    const definition = CUSTOM_NODE_SHAPE_DEFINITIONS[normalizedShapeKey];
    return {
        customIconKey: normalizedShapeKey,
        iconBackgroundImage: buildCustomNodeShapeDataUri(definition, nodeColor, normalizedShapeKey == 'lettuce' ? '#ffffff': nodeColor, 2)
    };
}
